{
  ".sigil/config.json": "{
  "sigilVersion": "0.8.0",
  "workspace": {
    "name": "mechanical-evaluation"
  },
  "files": {
    "include": [
      "**/*.sigil"
    ],
    "exclude": [
      "excluded/**"
    ]
  }
}
",
  "search/service.sigil": "component SearchService {
  goal {
    Find records matching supplied text.
  }
  interface {
    Accept a *query* and return *search results* as matching records.
  }
}
",
  "search/panel.sigil": "@search/service.sigil from SearchService import { query, search results }

component SearchPanel {
  goal {
    Help the user find records with query.
  }
  interface {
    Display search results for the active request while preserving visible records until the replacement request completes and supplies its own matching records.

    Follow the [display policy](../policy.md).

    Example payload stays exact.
    ```text
    literal  spacing and *not a Tag*
    ```
  }
  constraints {
    Only the active request may publish search results.
  }
}
",
  "policy.md": "Display only active-request results. Keep existing results visible until replacement results are ready.
",
  "intent.md": "Preserve the current search behavior, exact query and search results Tags, link target, and embedded payload. Revise only search/panel.sigil into a compact mechanically valid contract; keep existing results until replacement is ready.
",
  "unrelated.sigil": "component Notes {
  goal {
    Keep the user notes accessible.
  }
  interface {
    Return the saved notes on request.
  }
}
"
}

